#!/usr/bin/env python3
"""Generate the synthesizable symmetric Phase 5K FIR coefficient package."""

from __future__ import annotations

import argparse
from pathlib import Path

from verification.audio_phase5k import FIR_COEFFICIENTS, FIR_TAPS


DEFAULT_OUTPUT = Path("rtl/audio/nes_audio_fir_coeff_pkg.sv")


def package_text() -> str:
    half = FIR_COEFFICIENTS[: FIR_TAPS // 2 + 1]
    values = ",\n".join(
        f"        {'-' if coefficient < 0 else ''}19'sd{abs(coefficient)}"
        for coefficient in half
    )
    return f"""`timescale 1ns/1ps

// Generated by scripts/generate_audio_phase5k_coefficients.py.  The FIR is
// symmetric, so only taps 0..480 are stored; callers mirror the other half.
package nes_audio_fir_coeff_pkg;
    localparam int unsigned NES_AUDIO_FIR_TAPS = {FIR_TAPS};
    localparam int unsigned NES_AUDIO_FIR_HALF_TAPS = {len(half)};
    localparam int unsigned NES_AUDIO_FIR_COEFF_BITS = 18;
    localparam logic signed [18:0] NES_AUDIO_FIR_COEFFICIENTS [0:{len(half) - 1}] = '{{
{values}
    }};
endpackage
"""


def main() -> None:
    parser = argparse.ArgumentParser()
    parser.add_argument("--output", type=Path, default=DEFAULT_OUTPUT)
    parser.add_argument("--check", action="store_true")
    args = parser.parse_args()
    generated = package_text()
    if args.check:
        if not args.output.is_file() or args.output.read_text() != generated:
            raise SystemExit(f"stale Phase 5K FIR coefficients: {args.output}")
        print(f"Phase 5K FIR is reproducible: {args.output}")
        return
    args.output.parent.mkdir(parents=True, exist_ok=True)
    args.output.write_text(generated, encoding="ascii")


if __name__ == "__main__":
    main()
